382	          nState := s_ptw_req
383	          refillData(i).asid := tlb_req.asid
384	          // aligned vpn:
385	          refillData(i).vpn := Cat(tlb_req.vpn(SV.vpnLen-1, log2Up(nSectors)), 0.U(log2Up(nSectors).W))
386	          refillData(i).level := SV.levels.U
387	        }
388	      }
389	      is(s_ptw_req){
390	        when(ptw_req.fire){
391	          nState := s_ptw_rsp
392	        }.otherwise{ nState := s_ptw_req }
393	      }
394	      is(s_ptw_rsp){
395	        when(ptw_rsp.fire){
396	          refillIndex(i) := tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).setIndex
397	          refillData(i).ppns := ptw_rsp.bits.ppns
