399	          replace(i).access(tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).setIndex, refillWay(i))
400	
401	          tlb_rsp.id := tlb_req.id
402	          tlb_rsp.ppn := ptw_rsp.bits.ppns(tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).sectorIndex)
403	          tlb_rsp.flag := ptw_rsp.bits.flags(tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).sectorIndex)
404	          nState := s_reply
405	        }.otherwise{ nState := s_ptw_rsp }
406	      }
407	      is(s_reply){
