409	        when(out.fire){ nState := s_idle }.otherwise{ nState := s_reply }
410	      }
411	      is(s_invalid){
412	        when(storage.io.ready){
413	          nState := s_idle
414	        }.otherwise{
415	          nState := s_invalid
416	        }
417	      }
418	    }
